package courseschedule

import "testing"

func TestNoPrereqs(t *testing.T) {
	if !CanFinish(3, [][]int{}) {
		t.Fatal("want true")
	}
}

func TestSimpleChain(t *testing.T) {
	if !CanFinish(2, [][]int{{1, 0}}) {
		t.Fatal("want true")
	}
}

func TestSimpleCycle(t *testing.T) {
	if CanFinish(2, [][]int{{1, 0}, {0, 1}}) {
		t.Fatal("want false")
	}
}

func TestLongChain(t *testing.T) {
	if !CanFinish(4, [][]int{{1, 0}, {2, 1}, {3, 2}}) {
		t.Fatal("want true")
	}
}

func TestDiamond(t *testing.T) {
	if !CanFinish(4, [][]int{{1, 0}, {2, 0}, {3, 1}, {3, 2}}) {
		t.Fatal("want true")
	}
}

func TestThreeCycle(t *testing.T) {
	if CanFinish(3, [][]int{{0, 1}, {1, 2}, {2, 0}}) {
		t.Fatal("want false")
	}
}

func TestDisconnectedWithCycle(t *testing.T) {
	if CanFinish(5, [][]int{{1, 0}, {3, 4}, {4, 3}}) {
		t.Fatal("want false")
	}
}

func TestSelfLoop(t *testing.T) {
	if CanFinish(1, [][]int{{0, 0}}) {
		t.Fatal("want false")
	}
}
